654	    fn drop(&mut self) {
655	        let mut thread_timings = GLOBAL_THREAD_TIMINGS.lock();
656	
657	        let Some((index, _)) = thread_timings
658	            .iter()
659	            .enumerate()
660	            .find(|(_, t)| t.thread_id == self.thread_id)
