1095	
1096	        let frame = self.pending_frame.take();
1097	        let animation_interval =
1098	            if frame.is_some() && self.animating_at_last_present && window_active {
1099	                self.last_present_at
1100	                    .map(|last_present_at| present_end.duration_since(last_present_at))
1101	            } else {
1102	                None
1103	            };
1104	        let present_timing = PresentTiming {
1105	            window_id: self.window_id,
1106	            present_start,
1107	            present_end,
1108	            animation_interval,
1109	        };
1110	        journal::record_present(present_timing, frame);
1111	
1112	        if frame.is_none() {
1113	            return;
1114	        }
1115	
1116	        if let Some(animation_interval) = animation_interval {
1117	            self.present_interval_histogram
1118	                .record(animation_interval.as_nanos() as u64)
1119	                .ok();
1120	        }
1121	        record_frame_event(FrameEvent::Present(present_timing));
