1164	/// Records a frame event.
1165	///
1166	/// No-op unless profiler tracing is enabled via [`set_trace_enabled`].
1167	#[cfg(feature = "profiler")]
1168	pub fn record_frame_event(event: FrameEvent) {
1169	    if !trace_enabled() {
1170	        return;
1171	    }
1172	    std::hint::cold_path(); // optimize for when profiling is off
1173	
1174	    let mut frames = FRAME_TIMINGS.lock();
1175	    if frames.timings.len() >= MAX_FRAME_TIMINGS {
1176	        frames.timings.pop_front();
1177	    }
1178	    frames.timings.push_back(event);
1179	    frames.total_pushed += 1;
1180	}
