1196	#[cfg(feature = "profiler")]
1197	impl FrameTimingCollector {
1198	    /// Creates a collector that only sees frame events recorded from this point on.
1199	    pub fn new() -> Self {
1200	        Self {
1201	            cursor: FRAME_TIMINGS.lock().total_pushed,
1202	        }
1203	    }
1204	
1205	    /// Returns frame events recorded since the previous call (or since the
1206	    /// collector was created). If the ring buffer wrapped around since the
1207	    /// previous poll, the evicted entries are lost.
1208	    pub fn collect_unseen(&mut self) -> Vec<FrameEvent> {
1209	        let frames = FRAME_TIMINGS.lock();
1210	        let buffer_len = frames.timings.len() as u64;
1211	        let buffer_start = frames.total_pushed.saturating_sub(buffer_len);
1212	        let skip = self.cursor.saturating_sub(buffer_start) as usize;
1213	        let unseen = frames
1214	            .timings
1215	            .iter()
1216	            .skip(skip.min(frames.timings.len()))
1217	            .copied()
1218	            .collect();
1219	        self.cursor = frames.total_pushed;
1220	        unseen
1221	    }
1222	}
