1	//! A developer overlay that paints frame-time statistics directly into the
2	//! scene, bypassing layout, text, and view invalidation entirely (to avoid
3	//! infinitely triggering new frames).
4	
5	use crate::{
6	    BorderStyle, Bounds, ContentMask, Corners, Edges, Hsla, Pixels, Quad, ScaledPixels, Scene,
7	    Size, point, rgba, size, transparent_black,
8	};
9	use std::{collections::VecDeque, time::Duration};
10	
11	#[allow(missing_docs)]
12	#[derive(Copy, Clone, Debug, Default, PartialEq, Eq)]
13	pub enum DebugFrameOverlayMode {
14	    #[default]
15	    Hidden,
16	    Minimal,
17	    Full,
18	}
19	
20	impl DebugFrameOverlayMode {
21	    /// Returns the next mode in the Hidden → FrameTime → Detailed cycle.
22	    pub fn next(self) -> Self {
23	        match self {
24	            Self::Hidden => Self::Minimal,
25	            Self::Minimal => Self::Full,
26	            Self::Full => Self::Hidden,
27	        }
28	    }
29	}
30	
31	/// The number of most recent draw durations retained for percentile statistics.
32	const MAX_SAMPLES: usize = 1000;
33	
34	const GLYPH_WIDTH: usize = 5;
35	const GLYPH_HEIGHT: usize = 7;
36	/// Glyph advance and line advance, in font cells.
37	const CHAR_ADVANCE: f32 = (GLYPH_WIDTH + 1) as f32;
38	const LINE_ADVANCE: f32 = (GLYPH_HEIGHT + 2) as f32;
39	/// Padding between the panel edge and the text, in font cells.
40	const PANEL_PADDING: f32 = 2.0;
41	/// Margin between the panel and the window corner, in font cells.
42	const PANEL_MARGIN: f32 = 4.0;
43	/// Side of one square font cell, in logical pixels.
44	const CELL_SIZE: f32 = 2.0;
45	
46	fn text_color() -> Hsla {
47	    rgba(0x33ff33ff).into()
48	}
49	
50	fn panel_color() -> Hsla {
51	    rgba(0x000000aa).into()
52	}
53	
54	pub(crate) struct DebugFrameOverlay {
55	    mode: DebugFrameOverlayMode,
56	    draw_durations: VecDeque<Duration>,
57	    total_frame_count: u64,
58	}
59	
60	impl DebugFrameOverlay {
61	    pub(crate) fn new() -> Self {
62	        Self {
63	            mode: DebugFrameOverlayMode::default(),
64	            draw_durations: VecDeque::new(),
65	            total_frame_count: 0,
66	        }
67	    }
68	
69	    pub(crate) fn mode(&self) -> DebugFrameOverlayMode {
70	        self.mode
71	    }
72	
73	    pub(crate) fn set_mode(&mut self, mode: DebugFrameOverlayMode) {
74	        self.mode = mode;
75	    }
76	
77	    /// Clears the draw-duration samples, restarting the percentile window.
78	    /// The total frame count is left untouched.
79	    pub(crate) fn reset_stats(&mut self) {
80	        self.draw_durations.clear();
81	    }
82	
83	    pub(crate) fn is_enabled(&self) -> bool {
84	        self.mode != DebugFrameOverlayMode::Hidden
85	    }
86	
87	    pub(crate) fn record_frame(&mut self, draw_duration: Duration) {
88	        self.total_frame_count += 1;
89	        if self.draw_durations.len() >= MAX_SAMPLES {
90	            self.draw_durations.pop_front();
91	        }
92	        self.draw_durations.push_back(draw_duration);
93	    }
94	
95	    pub(crate) fn paint(&self, scene: &mut Scene, viewport_size: Size<Pixels>, scale_factor: f32) {
96	        if !self.is_enabled() {
97	            return;
98	        }
99	
100	        let lines = self.lines();
101	        let max_line_chars = lines.iter().map(|line| line.len()).max().unwrap_or(0);
102	        // Ensure at least one physical pixel per cell so the text stays legible
103	        // at fractional downscale factors.
104	        let cell = (CELL_SIZE * scale_factor).max(1.0);
105	
106	        let panel_width = cell * (max_line_chars as f32 * CHAR_ADVANCE + 2.0 * PANEL_PADDING);
107	        let panel_height = cell * (lines.len() as f32 * LINE_ADVANCE + 2.0 * PANEL_PADDING);
108	        let viewport = viewport_size.scale(scale_factor);
109	        let panel_left = viewport.width.0 - panel_width - cell * PANEL_MARGIN;
110	        let panel_top = cell * PANEL_MARGIN;
111	
112	        let content_mask = ContentMask {
113	            bounds: Bounds {
114	                origin: point(ScaledPixels(0.), ScaledPixels(0.)),
115	                size: viewport,
116	            },
117	        };
118	
119	        scene.insert_primitive(solid_quad(
120	            scaled_bounds(panel_left, panel_top, panel_width, panel_height),
121	            &content_mask,
122	            panel_color(),
123	        ));
124	
125	        let text_color = text_color();
126	        for (line_index, line) in lines.iter().enumerate() {
127	            let line_top = panel_top + cell * (PANEL_PADDING + line_index as f32 * LINE_ADVANCE);
128	            for (char_index, character) in line.chars().enumerate() {
129	                let Some(rows) = glyph(character) else {
130	                    continue;
131	                };
132	                let glyph_left =
133	                    panel_left + cell * (PANEL_PADDING + char_index as f32 * CHAR_ADVANCE);
134	                for (row_index, row) in rows.iter().enumerate() {
135	                    let row_top = line_top + cell * row_index as f32;
136	                    // Merge horizontal runs of lit cells into single quads.
137	                    let mut column = 0;
138	                    while column < GLYPH_WIDTH {
139	                        if row & (1 << (GLYPH_WIDTH - 1 - column)) == 0 {
140	                            column += 1;
141	                            continue;
142	                        }
143	                        let run_start = column;
144	                        while column < GLYPH_WIDTH && row & (1 << (GLYPH_WIDTH - 1 - column)) != 0 {
145	                            column += 1;
146	                        }
147	                        scene.insert_primitive(solid_quad(
148	                            scaled_bounds(
149	                                glyph_left + cell * run_start as f32,
150	                                row_top,
151	                                cell * (column - run_start) as f32,
152	                                cell,
153	                            ),
154	                            &content_mask,
155	                            text_color,
156	                        ));
157	                    }
158	                }
159	            }
160	        }
161	    }
162	
163	    fn lines(&self) -> Vec<String> {
164	        let current = self.draw_durations.back().copied();
165	        match self.mode {
166	            DebugFrameOverlayMode::Hidden => Vec::new(),
167	            DebugFrameOverlayMode::Minimal => vec![format_ms(current)],
168	            DebugFrameOverlayMode::Full => {
169	                let mut sorted: Vec<Duration> = self.draw_durations.iter().copied().collect();
170	                sorted.sort_unstable();
171	                let percentile = |numerator: usize| {
172	                    (!sorted.is_empty()).then(|| sorted[(sorted.len() - 1) * numerator / 100])
173	                };
174	                // Past five digits the count would break the column
175	                // alignment, so it saturates instead.
176	                let frame_count = if self.total_frame_count > 99_999 {
177	                    "LOTS".to_string()
178	                } else {
179	                    self.total_frame_count.to_string()
180	                };
181	                // Labels are padded to a uniform width so the fixed-width
182	                // durations start in the same column on every line.
183	                vec![
184	                    format!("CUR {}", format_ms(current)),
185	                    format!("1%  {}", format_ms(percentile(99))),
186	                    format!("10% {}", format_ms(percentile(90))),
187	                    format!("MAX {}", format_ms(sorted.last().copied())),
188	                    format!("FRAMES {frame_count:>5}"),
189	                ]
190	            }
191	        }
192	    }
193	}
194	
195	/// Formats as `abc.d MS`, right-aligned in room for three integer digits and
196	/// one decimal (padded with spaces, not zeroes), so stacked readouts align.
197	fn format_ms(duration: Option<Duration>) -> String {
198	    match duration {
199	        Some(duration) => {
200	            let ms = duration.as_secs_f32() * 1000.0;
201	            format!("{ms:>5.1} MS")
202	        }
203	        None => "   -- MS".into(),
204	    }
205	}
206	
207	fn scaled_bounds(left: f32, top: f32, width: f32, height: f32) -> Bounds<ScaledPixels> {
208	    Bounds {
209	        origin: point(ScaledPixels(left), ScaledPixels(top)),
210	        size: size(ScaledPixels(width), ScaledPixels(height)),
211	    }
212	}
213	
214	fn solid_quad(
215	    bounds: Bounds<ScaledPixels>,
216	    content_mask: &ContentMask<ScaledPixels>,
217	    color: Hsla,
218	) -> Quad {
219	    Quad {
220	        order: 0,
221	        border_style: BorderStyle::Solid,
222	        bounds,
223	        content_mask: *content_mask,
224	        background: color.into(),
225	        border_color: transparent_black(),
226	        corner_radii: Corners::default(),
227	        border_widths: Edges::default(),
228	    }
229	}
230	
231	/// Returns the 5x7 bitmap for the given character, one `u8` of column bits per
232	/// row with the most significant of the 5 bits leftmost. Only the characters
233	/// used by the overlay's readouts are defined.
234	fn glyph(character: char) -> Option<[u8; GLYPH_HEIGHT]> {
235	    Some(match character {
236	        '0' => [
237	            0b01110, 0b10001, 0b10011, 0b10101, 0b11001, 0b10001, 0b01110,
238	        ],
239	        '1' => [
240	            0b00100, 0b01100, 0b00100, 0b00100, 0b00100, 0b00100, 0b01110,
241	        ],
242	        '2' => [
243	            0b01110, 0b10001, 0b00001, 0b00010, 0b00100, 0b01000, 0b11111,
244	        ],
245	        '3' => [
246	            0b11111, 0b00010, 0b00100, 0b00010, 0b00001, 0b10001, 0b01110,
247	        ],
248	        '4' => [
249	            0b00010, 0b00110, 0b01010, 0b10010, 0b11111, 0b00010, 0b00010,
250	        ],
251	        '5' => [
252	            0b11111, 0b10000, 0b11110, 0b00001, 0b00001, 0b10001, 0b01110,
253	        ],
254	        '6' => [
255	            0b00110, 0b01000, 0b10000, 0b11110, 0b10001, 0b10001, 0b01110,
256	        ],
257	        '7' => [
258	            0b11111, 0b00001, 0b00010, 0b00100, 0b01000, 0b01000, 0b01000,
259	        ],
260	        '8' => [
261	            0b01110, 0b10001, 0b10001, 0b01110, 0b10001, 0b10001, 0b01110,
262	        ],
