61	/// Default target frame rate when a benchmark doesn't specify `fps = N`.
62	const DEFAULT_FPS: u64 = 120;
63	
64	const NANOS_PER_SECOND: u128 = 1_000_000_000;
65	
66	/// A small report produced by GPUI benchmarks.
67	#[derive(Clone)]
68	pub struct BenchReport {
69	    frame_snapshot: Rc<RefCell<WindowFrameSnapshot>>,
70	    frame_budget_nanos: u128,
71	}
72	
73	impl Default for BenchReport {
74	    fn default() -> Self {
75	        Self::with_fps(DEFAULT_FPS)
76	    }
77	}
78	
79	impl BenchReport {
80	    /// Creates a report whose per-frame budget is one frame at `fps` when
81	    /// counting frame budget overruns.
82	    pub fn with_fps(fps: u64) -> Self {
83	        assert!(fps > 0, "frame rate must be greater than zero");
84	        Self::with_frame_budget_nanos(NANOS_PER_SECOND / fps as u128)
85	    }
86	
87	    /// Creates a report that treats `frame_budget_nanos` as the per-frame budget
88	    /// when counting frame budget overruns.
89	    pub fn with_frame_budget_nanos(frame_budget_nanos: u128) -> Self {
90	        Self {
91	            frame_snapshot: Rc::new(RefCell::new(WindowFrameSnapshot::new())),
92	            frame_budget_nanos,
93	        }
94	    }
95	
96	    fn record_frame_timings<'i>(&self, events: impl IntoIterator<Item = &'i FrameEvent>) {
97	        let mut snapshot = self.frame_snapshot.borrow_mut();
98	        // `.ok()` on `record`: this operation is infallible (the histograms auto-resize).
99	        for event in events {
100	            match event {
101	                FrameEvent::Draw(timing) => {
102	                    snapshot
103	                        .draw
104	                        .record(timing.draw_duration().as_nanos() as u64)
105	                        .ok();
106	                    if let Some(dirty_to_draw) = timing.dirty_to_draw_duration() {
107	                        snapshot
108	                            .dirty_to_draw
109	                            .record(dirty_to_draw.as_nanos() as u64)
110	                            .ok();
111	                    }
112	                    if timing.invalidations > 0 {
113	                        snapshot
114	                            .invalidations_per_frame
115	                            .record(timing.invalidations)
116	                            .ok();
117	                    }
118	                }
119	                FrameEvent::Present(timing) => {
120	                    if let Some(animation_interval) = timing.animation_interval {
121	                        snapshot
122	                            .present_interval
123	                            .record(animation_interval.as_nanos() as u64)
124	                            .ok();
125	                    }
126	                }
127	            }
128	        }
129	    }
130	
131	    fn total_budget_overruns(&self, histogram: &Histogram<u64>) -> u64 {
132	        histogram
133	            .iter_recorded()
134	            .map(|value| {
135	                self.budget_overruns(Duration::from_nanos(value.value_iterated_to()))
136	                    * value.count_at_value()
137	            })
138	            .sum()
139	    }
140	
141	    /// Returns how many whole frame budgets `foreground_time` exceeded the
142	    /// per frame budget by. This is a synthetic proxy for missed frames: the
143	    /// benchmark harness has no vsync, so it counts how many frame deadlines
144	    /// would have elapsed while the foreground thread was busy.
145	    fn budget_overruns(&self, foreground_time: Duration) -> u64 {
146	        let foreground_nanos = foreground_time.as_nanos();
147	        if foreground_nanos <= self.frame_budget_nanos {
148	            return 0;
149	        }
150	
151	        let over_budget_nanos = foreground_nanos - self.frame_budget_nanos;
152	        over_budget_nanos.div_ceil(self.frame_budget_nanos) as u64
153	    }
154	
155	    /// Prints this report to stderr.
156	    pub fn print(&self, benchmark_name: Option<&'static str>) {
157	        let frame_snapshot = self.frame_snapshot.borrow();
158	        if frame_snapshot.is_empty() {
159	            return;
160	        }
161	
162	        let benchmark_name = benchmark_name.unwrap_or("unknown benchmark");
163	        eprintln!("GPUI bench report (all observed iterations): {benchmark_name}");
164	        eprintln!("  note: includes Criterion warmup/calibration");
165	        self.print_histogram("window dirty-to-draw", &frame_snapshot.dirty_to_draw);
166	        self.print_histogram("window draw", &frame_snapshot.draw);
167	        self.print_histogram("window present interval", &frame_snapshot.present_interval);
168	        if !frame_snapshot.invalidations_per_frame.is_empty() {
169	            eprintln!(
170	                "  invalidations per frame: mean {:.2}, max {}",
171	                frame_snapshot.invalidations_per_frame.mean(),
172	                frame_snapshot.invalidations_per_frame.max()
173	            );
174	        }
175	    }
176	
177	    fn print_histogram(&self, name: &str, histogram: &Histogram<u64>) {
178	        if histogram.is_empty() {
179	            return;
180	        }
181	
182	        let max_foreground_time = Duration::from_nanos(histogram.max());
183	        eprintln!("  {name}:");
184	        eprintln!("    samples: {}", histogram.len());
185	        eprintln!(
186	            "    mean: {}",
187	            format_duration(Duration::from_nanos(histogram.mean() as u64))
188	        );
189	        eprintln!(
190	            "    p50: {}",
191	            format_duration(Duration::from_nanos(histogram.value_at_quantile(0.50)))
192	        );
193	        eprintln!(
194	            "    p90: {}",
195	            format_duration(Duration::from_nanos(histogram.value_at_quantile(0.90)))
196	        );
197	        eprintln!(
198	            "    p95: {}",
199	            format_duration(Duration::from_nanos(histogram.value_at_quantile(0.95)))
200	        );
201	        eprintln!(
202	            "    p99: {}",
203	            format_duration(Duration::from_nanos(histogram.value_at_quantile(0.99)))
204	        );
205	        eprintln!("    max: {}", format_duration(max_foreground_time));
206	        eprintln!(
207	            "    frame budget overruns total: {}",
208	            self.total_budget_overruns(histogram)
209	        );
210	        eprintln!(
211	            "    frame budget overruns max: {}",
212	            self.budget_overruns(max_foreground_time)
213	        );
214	    }
215	}
