243	/// Enables profiler tracing for a measurement and collects its frame events.
244	///
245	/// The previous tracing state is restored on drop, so a panicking measurement
246	/// doesn't leave tracing enabled for unrelated code such as a later benchmark
247	/// in the same process.
248	struct TraceScope {
249	    collector: FrameTimingCollector,
250	    _trace_guard: profiler::TraceGuard,
251	}
252	
253	impl TraceScope {
254	    fn start() -> Self {
255	        let trace_guard = profiler::trace_scope();
256	        Self {
257	            collector: FrameTimingCollector::new(),
258	            _trace_guard: trace_guard,
259	        }
260	    }
261	
262	    fn finish(mut self) -> Vec<FrameEvent> {
263	        self.collector.collect_unseen()
264	    }
265	}
