278	impl<Output> Drop for MeasuredTaskOutput<Output> {
279	    fn drop(&mut self) {
280	        let trace_scope = self
281	            .trace_scope
282	            .take()
283	            .expect("measured task output should retain its trace scope");
284	        self.report
285	            .record_frame_timings(trace_scope.finish().iter());
286	    }
