289	fn run_task_to_completion<Output>(
290	    foreground_executor: &ForegroundExecutor,
291	    task: Task<Output>,
292	) -> Output
293	where
294	    Output: 'static,
295	{
296	    let output = Rc::new(RefCell::new(None));
297	    foreground_executor
298	        .spawn({
299	            let output = output.clone();
300	            async move {
301	                *output.borrow_mut() = Some(task.await);
302	            }
303	        })
304	        .detach();
305	
306	    foreground_executor
307	        .dispatcher()
308	        .as_threaded()
309	        .expect("BenchAppContext requires a ThreadedDispatcher")
310	        .run_until(|| output.borrow_mut().take())
311	}
