313	/// A GPUI app context for Criterion benchmarks.
314	///
315	/// `BenchAppContext` is intentionally separate from `TestAppContext`: it owns a
316	/// benchmark app instance and exposes only the app/window operations needed by
317	/// benchmark setup. Criterion remains responsible for the measured loop via its
318	/// `Bencher` API.
319	#[derive(Clone)]
320	pub struct BenchAppContext<'a, 'measurement> {
321	    app: Rc<AppCell>,
322	    background_executor: BackgroundExecutor,
323	    foreground_executor: ForegroundExecutor,
324	    benchmark_name: Option<&'static str>,
325	    bencher: Rc<RefCell<Option<&'a mut criterion::Bencher<'measurement>>>>,
326	    report: BenchReport,
327	}
328	
329	impl<'a, 'measurement> BenchAppContext<'a, 'measurement> {
330	    /// Creates a new benchmark app context backed by the provided platform.
331	    ///
332	    /// The platform's executors must be backed by a [`ThreadedDispatcher`]
333	    /// (see [`bench_platform`]) so the context can drain foreground work via
334	    /// [`Self::run_until_idle`]; panics otherwise.
335	    pub fn new(
336	        platform: Rc<dyn Platform>,
337	        benchmark_name: Option<&'static str>,
338	        bencher: &'a mut criterion::Bencher<'measurement>,
339	    ) -> Self {
340	        Self::build(platform, benchmark_name, bencher, BenchReport::default())
341	    }
342	
343	    /// Creates a new benchmark app context backed by the provided platform.
344	    ///
345	    /// The platform's executors must be backed by a [`ThreadedDispatcher`]
346	    /// (see [`bench_platform`]) so the context can drain foreground work via
347	    /// [`Self::run_until_idle`]; panics otherwise.
348	    #[doc(hidden)]
349	    pub fn new_with_platform_and_report(
350	        platform: Rc<dyn Platform>,
351	        benchmark_name: Option<&'static str>,
352	        bencher: &'a mut criterion::Bencher<'measurement>,
353	        report: BenchReport,
354	    ) -> Self {
355	        Self::build(platform, benchmark_name, bencher, report)
356	    }
357	
358	    fn build(
359	        platform: Rc<dyn Platform>,
360	        benchmark_name: Option<&'static str>,
361	        bencher: &'a mut criterion::Bencher<'measurement>,
362	        report: BenchReport,
363	    ) -> Self {
364	        let background_executor = platform.background_executor();
365	        // Validate up front so misconfiguration fails at construction with a
366	        // clear message instead of deep inside `run_until_idle`.
367	        assert!(
368	            background_executor.dispatcher().as_threaded().is_some(),
369	            "BenchAppContext requires a platform whose executors are backed by a \
370	             ThreadedDispatcher; construct one with gpui::bench_platform"
371	        );
372	        let foreground_executor = platform.foreground_executor();
373	        let asset_source = Arc::new(());
374	        let http_client = http_client::FakeHttpClient::with_404_response();
375	        let app = App::new_app(platform, asset_source, http_client);
376	
377	        Self {
378	            app,
379	            background_executor,
380	            foreground_executor,
381	            benchmark_name,
382	            bencher: Rc::new(RefCell::new(Some(bencher))),
383	            report,
384	        }
385	    }
386	
387	    /// The benchmark function name that created this context.
388	    pub fn benchmark_name(&self) -> Option<&'static str> {
389	        self.benchmark_name
390	    }
391	
392	    /// Returns the background executor used by this benchmark app.
393	    pub fn background_executor(&self) -> &BackgroundExecutor {
394	        &self.background_executor
395	    }
396	
397	    /// Returns the foreground executor used by this benchmark app.
398	    pub fn foreground_executor(&self) -> &ForegroundExecutor {
399	        &self.foreground_executor
400	    }
401	
402	    /// Updates the app and flushes synchronous GPUI effects afterward.
403	    pub fn update<R>(&mut self, update: impl FnOnce(&mut App) -> R) -> R {
404	        let mut app = self.app.borrow_mut();
405	        app.update(update)
406	    }
407	
408	    /// Reads app state.
409	    pub fn read<R>(&self, read: impl FnOnce(&App) -> R) -> R {
410	        let app = self.app.borrow();
411	        read(&app)
412	    }
413	
414	    /// Runs queued foreground tasks on this thread and waits for in flight
415	    /// background work to finish. Timers that aren't due yet are not waited
416	    /// for (see [`ThreadedDispatcher::run_until_idle`]).
417	    pub fn run_until_idle(&self) {
418	        self.background_executor
419	            .dispatcher()
420	            .as_threaded()
421	            .expect("validated in BenchAppContext::build")
422	            .run_until_idle();
423	    }
424	
425	    /// Alternates draining queued work with GPUI update cycles until neither
426	    /// makes progress, so state dropped by benchmark code is fully released.
427	    ///
428	    /// Dropped entities are released only inside an update's effect flush, and
429	    /// releases cascade: one flush drops the entities whose handles are gone,
430	    /// their drops release further handles and can queue foreground work, and
431	    /// a later flush collects those. Executor pumping alone never runs a
432	    /// flush, so without this dropped state would linger in the entity map
433	    /// until some woken task happened to run an update. Production gets this
434	    /// cadence for free from frames and input events.
435	    pub fn settle(&mut self) {
436	        let dispatcher = self.background_executor.dispatcher().clone();
437	        let dispatcher = dispatcher
438	            .as_threaded()
439	            .expect("validated in BenchAppContext::build");
440	        loop {
441	            self.run_until_idle();
442	            self.update(|_| ());
443	            if dispatcher.is_idle() {
444	                return;
445	            }
446	        }
447	    }
448	
449	    /// Runs main-thread tasks until `ready` returns a value.
450	    ///
451	    /// Unlike [`Self::run_until_idle`], this returns as soon as `ready`
452	    /// reports completion, leaving any remaining queued work pending.
453	    pub fn run_until<R>(&self, ready: impl FnMut() -> Option<R>) -> R {
454	        self.background_executor
455	            .dispatcher()
456	            .as_threaded()
457	            .expect("validated in BenchAppContext::build")
458	            .run_until(ready)
459	    }
460	
461	    /// Measures a generic benchmark workload using Criterion's iteration loop.
462	    ///
463	    /// The closure is invoked once per Criterion iteration with this
464	    /// benchmark app context so it can update GPUI state.
465	    ///
466	    /// Any window draws triggered by the workload are recorded into the
467	    /// benchmark's frame report through the GPUI frame profiler.
468	    pub fn bench_iter(&mut self, mut benchmark: impl FnMut(&mut Self)) {
469	        let bencher = self.take_bencher("bench_iter");
470	        let collector = TraceScope::start();
471	        let mut benchmark = || benchmark(self);
472	        bencher.iter(&mut benchmark);
473	        self.report.record_frame_timings(collector.finish().iter());
474	        self.replace_bencher(bencher);
475	    }
476	
477	    /// Measures a GPUI task to completion using Criterion's iteration loop.
478	    ///
479	    /// The closure is invoked once per Criterion iteration. The returned task
480	    /// may depend on foreground work, background work, timers, or external
481	    /// workers that wake GPUI tasks. Its output is dropped after the timed
482	    /// interval.
483	    ///
484	    /// Any window draws triggered by the task are recorded into the benchmark's
485	    /// frame report through the GPUI frame profiler.
486	    pub fn bench_task<Output>(&mut self, mut benchmark: impl FnMut(&mut Self) -> Task<Output>)
487	    where
488	        Output: 'static,
489	    {
490	        self.bench_batched_task_internal("bench_task", |_| (), |_, cx| benchmark(cx));
491	    }
492	
493	    /// Measures a GPUI task with per-iteration setup outside the timed interval.
494	    ///
495	    /// `setup` runs before timing starts. The returned input is passed by mutable
496	    /// reference to `benchmark`, which returns the task whose completion is
497	    /// measured. Both the setup input and task output are dropped after timing
498	    /// stops.
499	    ///
500	    /// Each iteration is kept in its own Criterion batch so profiler tracing and
501	    /// destruction cannot overlap adjacent measurements.
502	    pub fn bench_batched_task<Input, Output>(
503	        &mut self,
504	        setup: impl FnMut(&mut Self) -> Input,
505	        benchmark: impl FnMut(&mut Input, &mut Self) -> Task<Output>,
506	    ) where
507	        Output: 'static,
508	    {
509	        self.bench_batched_task_internal("bench_batched_task", setup, benchmark);
510	    }
511	
512	    fn bench_batched_task_internal<Input, Output>(
513	        &mut self,
514	        benchmark_kind: &str,
515	        mut setup: impl FnMut(&mut Self) -> Input,
516	        mut benchmark: impl FnMut(&mut Input, &mut Self) -> Task<Output>,
517	    ) where
518	        Output: 'static,
519	    {
520	        let bencher = self.take_bencher(benchmark_kind);
521	        let mut setup_context = self.clone();
522	        let mut benchmark_context = self.clone();
523	        let foreground_executor = self.foreground_executor.clone();
524	        let report = self.report.clone();
525	
526	        bencher.iter_batched_ref(
527	            || {
528	                // The previous iteration's input and output were just
529	                // dropped; settling here releases their entities before the
530	                // next setup, so per-iteration state cannot accumulate
531	                // across a measurement.
532	                setup_context.settle();
533	                MeasuredTaskInput {
534	                    input: setup(&mut setup_context),
535	                    trace_scope: Some(TraceScope::start()),
536	                }
537	            },
538	            |measured_input| {
539	                let task = benchmark(&mut measured_input.input, &mut benchmark_context);
540	                let output = run_task_to_completion(&foreground_executor, task);
541	                MeasuredTaskOutput {
542	                    trace_scope: measured_input.trace_scope.take(),
543	                    report: report.clone(),
544	                    _output: output,
545	                }
546	            },
547	            criterion::BatchSize::PerIteration,
548	        );
549	        self.replace_bencher(bencher);
550	    }
551	
552	    /// Measures frame latency after updating a GPUI entity in its current window.
553	    ///
554	    /// Each iteration runs `update` against the entity in its current window. In
555	    /// bench builds, flushing the update's effects synchronously draws dirty
556	    /// windows. The entity should be part of the window's render tree, such as the
557	    /// root view or a child of it.
558	    ///
559	    /// Frame events are collected through the GPUI frame profiler
560	    /// ([`crate::profiler::record_frame_event`]), which is enabled for the
561	    /// duration of the measurement.
562	    pub fn bench_renderer<V>(
563	        &mut self,
564	        view: Entity<V>,
565	        mut update: impl FnMut(&mut V, &mut Window, &mut Context<V>),
566	    ) where
567	        V: 'static + Render,
568	    {
569	        let bencher = self.take_bencher("bench_renderer");
570	        let window_id = self
571	            .with_window(view.entity_id(), |window, _| {
572	                window.window_handle().window_id()
573	            })
574	            .expect("cannot benchmark renderer for entity without a current window");
575	
576	        let dispatcher = self.background_executor.dispatcher().clone();
577	        let collector = TraceScope::start();
578	
579	        let mut benchmark = || {
580	            // Work already queued at frame start delays the frame in
581	            // production too, so run it inside the measured interval.
582	            dispatcher
583	                .as_threaded()
584	                .expect("validated in BenchAppContext::build")
585	                .run_ready_main_tasks();
586	            self.with_window(view.entity_id(), |window, cx| {
587	                view.update(cx, |view, cx| update(view, window, cx));
588	            })
589	            .expect("cannot benchmark renderer for entity without a current window");
590	            // Submit the frame drawn by the update's effect flush, mirroring
591	            // production where every drawn frame is presented. With a headless
592	            // renderer this includes scene submission to the GPU.
593	            self.with_window(view.entity_id(), |window, _| {
594	                window.present_if_needed();
595	            })
596	            .expect("cannot benchmark renderer for entity without a current window");
597	        };
598	        bencher.iter(&mut benchmark);
599	
600	        let events = collector.finish();
601	        self.report
602	            .record_frame_timings(events.iter().filter(|event| match event {
603	                FrameEvent::Draw(timing) => timing.window_id == window_id,
604	                FrameEvent::Present(timing) => timing.window_id == window_id,
605	            }));
606	        self.replace_bencher(bencher);
607	    }
