609	    /// Adds a window with an empty root view for benchmark setup.
610	    pub fn add_empty_window(&mut self) -> BenchWindowContext<'a, 'measurement> {
611	        let bounds = {
612	            let app = self.app.borrow();
613	            Bounds::maximized(None, &app)
614	        };
615	        let window = {
616	            let mut app = self.app.borrow_mut();
617	            let window: AnyWindowHandle = app
618	                .open_window(
619	                    WindowOptions {
620	                        window_bounds: Some(WindowBounds::Windowed(bounds)),
621	                        ..Default::default()
622	                    },
623	                    |_, cx| cx.new(|_| Empty),
624	                )
625	                .expect("failed to open benchmark window")
626	                .into();
627	            window
628	        };
629	
630	        self.run_until_idle();
631	        BenchWindowContext {
632	            cx: self.clone(),
633	            window,
634	        }
