653	    /// Cancels any timers still armed on the shared dispatcher and drains the
654	    /// work that cancellation unblocks so they can't fire during a later
655	    /// benchmark; assumes no other `BenchAppContext` is live on this thread.
656	    pub fn teardown(mut self) {
657	        self.run_until_idle();
658	        self.update(|cx| {
659	            cx.quit();
660	        });
661	        self.run_until_idle();
662	
663	        let dispatcher = self.background_executor.dispatcher();
664	        let dispatcher = dispatcher
665	            .as_threaded()
666	            .expect("validated in BenchAppContext::build");
667	
668	        drop(self.app);
669	        drop(self.foreground_executor);
670	
671	        for _ in 0..100 {
672	            if dispatcher.cancel_pending_timers() == 0 {
673	                return;
674	            }
675	            dispatcher.run_until_idle();
676	        }
677	        panic!(
678	            "benchmark teardown kept scheduling timers: {}",
679	            dispatcher.debug_state()
680	        );
681	    }
