                crate::Bounds {
                    origin: hitbox.origin
                        + crate::point(crate::px(0.), FONT_SIZE - px(2.)),
                    size: crate::Size {
                        width: text_bounds.size.width,
                        height: crate::px(1.),
                    },
                },
                crate::red(),
                BorderStyle::default(),
            ))
        }
    }
