                   grid.generation += 1;
                   cx.notify();
               });
           });
       });
   }
   ```

   注：`window.replace_root` 返回新根视图的句柄，实践中直接保存它的返回值再对其 `notify` 即可，上面为展示两种写法而并列写出；实际使用选一种。

